package com.creepsinc.clanbank;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Run this class directly from IntelliJ (right-click > Run) to launch a full
 * RuneLite client with this plugin already loaded and enabled — no need for
 * any third-party sideloading tool. This is RuneLite's own standard way of
 * running a plugin under development; it uses your existing RuneLite
 * profile/login from ~/.runelite, same as your normal client.
 */
public class ClanBankPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ClanBankPlugin.class);
		RuneLite.main(args);
	}
}

package com.creepsinc.clanbank;

/**
 * Shared number formatting. The sidebar panel is only 225px wide and the
 * overlay narrower still, so fully written-out gp values ("2,169,207 /
 * 2,500,000 gp") overflow their row — they collide with their own label or
 * get ellipsized. Everything user-facing shows the compact form and carries
 * the exact figure in a tooltip where one is available.
 */
final class ClanBankFormat
{
	private ClanBankFormat()
	{
	}

	static String compactGp(long value)
	{
		if (value >= 1_000_000)
		{
			return trimZero(value / 1_000_000d) + "M";
		}
		if (value >= 1_000)
		{
			return trimZero(value / 1_000d) + "K";
		}
		return String.valueOf(value);
	}

	static String exactGp(long value)
	{
		return String.format("%,d gp", value);
	}

	private static String trimZero(double v)
	{
		String s = String.format("%.1f", v);
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}
}

package com.creepsinc.clanbank;

import java.io.IOException;
import java.util.Collections;
import java.util.List;

/**
 * A bot API call reached the server and got a well-formed error response
 * (bad quantity, item not found, over the loan cap, etc.) — as opposed to
 * a plain IOException, which means the bot itself wasn't reachable at all.
 */
class ClanBankApiException extends IOException
{
	private final List<String> options;
	private final List<String> suggestions;

	ClanBankApiException(String message, List<String> options, List<String> suggestions)
	{
		super(message);
		this.options = options == null ? Collections.emptyList() : options;
		this.suggestions = suggestions == null ? Collections.emptyList() : suggestions;
	}

	List<String> getOptions()
	{
		return options;
	}

	List<String> getSuggestions()
	{
		return suggestions;
	}
}

package com.creepsinc.clanbank;

import java.util.List;

/**
 * Mirrors the JSON shape returned by the bot's GET /status?rsn=... endpoint.
 * Field names match exactly since Gson deserializes by name.
 */
public class ClanBankStatus
{
	public boolean linked;
	public String clanName;
	public String discordTag;
	public long loanCapGp;
	public boolean noLimit;
	public long totalOutstandingGp;
	public int pendingCount;
	public List<LoanEntry> loans;

	public static class LoanEntry
	{
		public String itemName;
		public String repaymentType; // "item" or "gp"
		public long quantityOwed;
		public long gpOwed;
		public String finalProduct;
	}
}

package com.creepsinc.clanbank;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.Box;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.DefaultComboBoxModel;
import javax.swing.DefaultListCellRenderer;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JSeparator;
import javax.swing.JSpinner;
import javax.swing.JTextField;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.http.api.item.ItemPrice;

/**
 * Full detail view for the clan bank status — opened from the sidebar icon.
 * The overlay only shows a compact "owed / pending" summary; this panel has
 * everything else: discord link, per-item breakdown with icons, and forms
 * to request or settle a loan directly without going to Discord (both still
 * go through the exact same officer-approval flow as the slash commands).
 */
class ClanBankPanel extends PluginPanel
{
	private static final int ICON_SIZE = 32;
	private static final int CARD_RADIUS = 8;
	private static final int ICON_TILE_RADIUS = 6;
	private static final Color CARD_BACKGROUND = ColorScheme.DARKER_GRAY_COLOR;
	private static final Color ICON_TILE_BACKGROUND = ColorScheme.DARK_GRAY_HOVER_COLOR;
	private static final Color OK_GREEN = new Color(0x8B, 0xC3, 0x4A);
	private static final Color CAP_BAR_BACKGROUND = new Color(0x3A, 0x3A, 0x3A);

	// Plain JPanel with a rounded-rect background instead of Swing's default
	// square fill — used for every card so the panel doesn't look like a
	// stack of flat rectangles butted up against each other.
	private static class RoundedPanel extends JPanel
	{
		private final int radius;

		RoundedPanel(java.awt.LayoutManager layout, int radius)
		{
			super(layout);
			this.radius = radius;
			setOpaque(false);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(getBackground());
			g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), radius, radius));
			g2.dispose();
			super.paintComponent(g);
		}
	}

	// Thin rounded bar showing gp-out-of-cap at a glance, mirroring the
	// overlay's progress bar so the two surfaces read consistently.
	private static class MiniProgressBar extends JComponent
	{
		private double value;
		private double maximum = 1;
		private Color foreground = OK_GREEN;

		MiniProgressBar()
		{
			// Only maximumSize should be unbounded (lets BoxLayout stretch this
			// to the container's full width) — an unbounded preferredSize
			// corrupts width negotiation for every ancestor container up the
			// tree, which is what was squashing the whole status card.
			setPreferredSize(new Dimension(1, 5));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 5));
			setAlignmentX(LEFT_ALIGNMENT);
		}

		void setProgress(double value, double maximum, Color foreground)
		{
			this.value = value;
			this.maximum = Math.max(maximum, 1);
			this.foreground = foreground;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int h = getHeight();
			g2.setColor(CAP_BAR_BACKGROUND);
			g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), h, h, h));
			float ratio = (float) Math.min(1.0, Math.max(0.0, value / maximum));
			int fillWidth = Math.round(getWidth() * ratio);
			if (fillWidth > 0)
			{
				g2.setColor(foreground);
				g2.fill(new RoundRectangle2D.Float(0, 0, fillWidth, h, h, h));
			}
			g2.dispose();
		}
	}

	// JButton with its default square background/border suppressed and a
	// hand-painted rounded rect drawn instead — plain JButton has no
	// border-radius support without this.
	private static class RoundedButton extends JButton
	{
		private final int radius;

		RoundedButton(String text, int radius)
		{
			super(text);
			this.radius = radius;
			setContentAreaFilled(false);
			setBorderPainted(false);
			setFocusPainted(false);
			setOpaque(false);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(getModel().isRollover() ? getBackground().darker() : getBackground());
			g2.fill(new RoundRectangle2D.Float(0, 0, getWidth(), getHeight(), radius, radius));
			g2.dispose();
			super.paintComponent(g);
		}
	}

	// Rebuilt every poll refresh (~30s) — read-only status display.
	private final JPanel content = new JPanel();
	// Built once — action forms live here so in-progress user input (typed
	// item names, quantities) doesn't get wiped out by a poll refresh.
	private final JPanel actions = new JPanel();

	@Inject
	private ItemManager itemManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Client client;

	@Inject
	private ClanBankConfig config;

	@Inject
	private ClanBankApiClient apiClient;

	// Item name -> resolved icon, so repeated poll refreshes don't re-search
	// the same items over and over.
	private final Map<String, AsyncBufferedImage> iconCache = new ConcurrentHashMap<>();

	// --- Request Item form state ---
	private JTextField requestItemField;
	private JPanel suggestionsPanel;
	private JPanel previewCard;
	private JLabel previewIcon;
	private JLabel previewName;
	private JLabel previewMeta;
	private JLabel previewNotes;
	private JPanel requestFinalProductArea;
	private JComboBox<String> requestFinalProductCombo;
	private JTextField requestFinalProductFreeText;
	private JSpinner requestQuantitySpinner;
	private JLabel requestSummaryLabel;
	private JButton requestSubmitButton;
	private JLabel requestStatusLabel;
	private ItemLookupResult currentLookup;
	private final Timer searchDebounce = new Timer(350, e -> performSearch());

	// --- Return / Settle form state ---
	private JComboBox<LoanChoice> returnLoanCombo;
	private JSpinner returnAmountSpinner;
	private JLabel returnAmountCaption;
	private JButton returnSubmitButton;
	private JLabel returnStatusLabel;
	private JLabel returnEmptyLabel;
	private JPanel returnFormCard;

	@Inject
	private ClanBankPanel()
	{
		super(false);
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		searchDebounce.setRepeats(false);

		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBorder(new EmptyBorder(10, 10, 0, 10));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setAlignmentX(LEFT_ALIGNMENT);
		// content starts empty and is rebuilt later once status loads, unlike
		// actions (populated immediately below) — without an explicit maximum
		// width it can get stuck sized to that empty first layout pass instead
		// of stretching to match actions once real content exists.
		content.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

		actions.setLayout(new BoxLayout(actions, BoxLayout.Y_AXIS));
		actions.setBorder(new EmptyBorder(10, 10, 10, 10));
		actions.setBackground(ColorScheme.DARK_GRAY_COLOR);
		actions.setAlignmentX(LEFT_ALIGNMENT);
		buildActionForms();

		JPanel outer = new JPanel();
		outer.setLayout(new BoxLayout(outer, BoxLayout.Y_AXIS));
		outer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		outer.add(content);
		outer.add(actions);
		add(outer, BorderLayout.NORTH);
	}

	void update(ClanBankStatus status, String lastError)
	{
		SwingUtilities.invokeLater(() -> render(status, lastError));
	}

	// Plain Swing look-and-feel renders these as light/white boxes that clash
	// hard with the dark theme — recolor them to match. Corners stay square;
	// getting a JTextField/JComboBox/JSpinner's own corners rounded needs a
	// custom UI delegate, which is a much bigger job than a color pass.
	private static final Color FIELD_BACKGROUND = new Color(0x1E, 0x1E, 0x1E);

	private void styleField(JComponent field)
	{
		field.setBackground(FIELD_BACKGROUND);
		field.setForeground(Color.WHITE);
		field.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
		field.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 1),
			new EmptyBorder(4, 6, 4, 6)
		));
		if (field instanceof JTextField)
		{
			((JTextField) field).setCaretColor(Color.WHITE);
		}
	}

	private JLabel label(String text, Color color, float size, boolean bold)
	{
		JLabel l = new JLabel(text);
		l.setForeground(color);
		l.setFont(new Font(Font.SANS_SERIF, bold ? Font.BOLD : Font.PLAIN, 1).deriveFont(size));
		return l;
	}

	// A Y_AXIS BoxLayout only stretches children to the container's full width
	// if every child shares the same alignmentX. Mix a default-aligned child
	// (0.5) in with left-aligned ones (0.0) and BoxLayout reserves space for a
	// notional "left half", leaving the left-aligned children rendering at
	// roughly half width. So: cap the width, and pin the alignment.
	//
	// Never set preferredSize here — callers invoke this before adding
	// children, so capturing the current preferred height would pin the
	// component to zero height and erase its contents.
	private void fillWidth(JComponent c, int width)
	{
		c.setAlignmentX(LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(width, Integer.MAX_VALUE));
	}

	private JPanel titleBar(String text)
	{
		JPanel titleBar = new JPanel(new BorderLayout());
		titleBar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		titleBar.setBorder(new EmptyBorder(0, 0, 8, 0));
		fillWidth(titleBar, CARD_TARGET_WIDTH);

		// Smaller than before (was 15f) — clan names get appended with
		// " Clan Bank", and the sans-serif font swap runs noticeably wider
		// per character than the old pixel font did, so 15f was clipping.
		JLabel title = label(text, ColorScheme.BRAND_ORANGE, 13f, true);
		title.setHorizontalAlignment(SwingConstants.CENTER);
		titleBar.add(title, BorderLayout.NORTH);

		JSeparator sep = new JSeparator();
		sep.setForeground(ColorScheme.BRAND_ORANGE);
		titleBar.add(sep, BorderLayout.SOUTH);
		return titleBar;
	}

	// content/actions both use EmptyBorder(10, ..., 10) — 20px of horizontal
	// inset — so this is what a card actually has to fill.
	private static final int CARD_TARGET_WIDTH = PluginPanel.PANEL_WIDTH - 20;
	// A card's own EmptyBorder(10, 12, 10, 12) eats another 24px — this is
	// what something living *inside* a card (like previewCard) has to fill.
	private static final int CARD_INNER_WIDTH = CARD_TARGET_WIDTH - 24;

	private JPanel card(JPanel inner)
	{
		JPanel wrapper = new RoundedPanel(new BorderLayout(), CARD_RADIUS);
		wrapper.setBackground(CARD_BACKGROUND);
		wrapper.setBorder(new EmptyBorder(10, 12, 10, 12));
		inner.setBackground(CARD_BACKGROUND);
		wrapper.add(inner, BorderLayout.CENTER);
		fillWidth(wrapper, CARD_TARGET_WIDTH);
		return wrapper;
	}

	// Small left-aligned uppercase label for a sub-section within a card
	// stack ("ITEMS ON LOAN", "REQUEST ITEM"...) — the panel has one big
	// centered title at the very top; everything below it uses this instead
	// of another full title bar, so the hierarchy stays readable at a glance.
	private JLabel sectionLabel(String text)
	{
		JLabel l = label(text.toUpperCase(), ColorScheme.BRAND_ORANGE, 11f, true);
		l.setAlignmentX(LEFT_ALIGNMENT);
		return l;
	}

	// Struts default to CENTER alignmentX, which is enough on its own to
	// trigger the mixed-alignment shrinking described on fillWidth — every
	// child of a Y_AXIS BoxLayout has to agree, spacers included.
	private static Component strut(int px)
	{
		Box.Filler filler = (Box.Filler) Box.createVerticalStrut(px);
		filler.setAlignmentX(LEFT_ALIGNMENT);
		return filler;
	}

	private void addVerticalGap(int px)
	{
		content.add(strut(px));
	}

	private void addSpacer(JPanel target, int px)
	{
		target.add(strut(px));
	}

	// ------------------------------------------------------------------
	// Read-only status display (rebuilt every poll)
	// ------------------------------------------------------------------

	private void render(ClanBankStatus status, String lastError)
	{
		content.removeAll();
		String clanTitle = status != null && status.clanName != null ? status.clanName + " Clan Bank" : "Clan Bank";
		content.add(titleBar(clanTitle));

		if (lastError != null && status == null)
		{
			JPanel msg = new JPanel();
			msg.setLayout(new BoxLayout(msg, BoxLayout.Y_AXIS));
			fillWidth(msg, CARD_INNER_WIDTH);
			msg.add(label(lastError, ColorScheme.PROGRESS_ERROR_COLOR, 12f, true));
			content.add(card(msg));
			refreshReturnOptions(null);
			finishRender();
			return;
		}

		if (status == null)
		{
			JPanel msg = new JPanel();
			msg.setLayout(new BoxLayout(msg, BoxLayout.Y_AXIS));
			fillWidth(msg, CARD_INNER_WIDTH);
			msg.add(label("Loading...", ColorScheme.LIGHT_GRAY_COLOR, 12f, false));
			content.add(card(msg));
			refreshReturnOptions(null);
			finishRender();
			return;
		}

		if (!status.linked)
		{
			JPanel msg = new JPanel();
			msg.setLayout(new BoxLayout(msg, BoxLayout.Y_AXIS));
			fillWidth(msg, CARD_INNER_WIDTH);
			msg.add(label("No bank activity found", ColorScheme.LIGHT_GRAY_COLOR, 12f, true));
			addVerticalGap(4);
			for (String l : new String[] {
				"Borrow, return, or donate something",
				"via the Discord bank panel, or run",
				"/link-rsn if your Discord name",
				"doesn't match your RSN.",
			})
			{
				msg.add(label(l, ColorScheme.LIGHT_GRAY_COLOR, 11f, false));
			}
			content.add(card(msg));
			refreshReturnOptions(null);
			finishRender();
			return;
		}

		// --- Status card: discord link, owed total, pending count ---
		JPanel statusCard = new JPanel();
		statusCard.setLayout(new BoxLayout(statusCard, BoxLayout.Y_AXIS));
		fillWidth(statusCard, CARD_INNER_WIDTH);
		statusCard.add(label("Linked as " + status.discordTag, ColorScheme.LIGHT_GRAY_COLOR, 11f, false));
		addSpacer(statusCard, 4);

		boolean overCap = !status.noLimit && status.totalOutstandingGp >= status.loanCapGp;
		JPanel owedRow = new JPanel(new BorderLayout());
		owedRow.setBackground(CARD_BACKGROUND);
		fillWidth(owedRow, CARD_INNER_WIDTH);
		owedRow.add(label("Owed", ColorScheme.LIGHT_GRAY_COLOR, 12f, false), BorderLayout.WEST);
		JLabel owedValue = label(
			status.noLimit
				? ClanBankFormat.compactGp(status.totalOutstandingGp) + " gp"
				: ClanBankFormat.compactGp(status.totalOutstandingGp) + " / " + ClanBankFormat.compactGp(status.loanCapGp) + " gp",
			overCap ? ColorScheme.PROGRESS_ERROR_COLOR : Color.WHITE,
			12f,
			true
		);
		owedValue.setToolTipText(status.noLimit
			? ClanBankFormat.exactGp(status.totalOutstandingGp) + " out, no cap"
			: ClanBankFormat.exactGp(status.totalOutstandingGp) + " out of a " + ClanBankFormat.exactGp(status.loanCapGp) + " cap");
		owedValue.setHorizontalAlignment(SwingConstants.RIGHT);
		owedRow.add(owedValue, BorderLayout.EAST);
		statusCard.add(owedRow);

		if (!status.noLimit)
		{
			addSpacer(statusCard, 5);
			MiniProgressBar capBar = new MiniProgressBar();
			fillWidth(capBar, CARD_INNER_WIDTH);
			capBar.setProgress(status.totalOutstandingGp, status.loanCapGp, overCap ? ColorScheme.PROGRESS_ERROR_COLOR : OK_GREEN);
			statusCard.add(capBar);
		}
		addSpacer(statusCard, 4);

		JPanel pendingRow = new JPanel(new BorderLayout());
		pendingRow.setBackground(CARD_BACKGROUND);
		fillWidth(pendingRow, CARD_INNER_WIDTH);
		pendingRow.add(label("Pending approval", ColorScheme.LIGHT_GRAY_COLOR, 12f, false), BorderLayout.WEST);
		JLabel pendingValue = label(
			String.valueOf(status.pendingCount),
			status.pendingCount > 0 ? ColorScheme.BRAND_ORANGE : Color.WHITE,
			12f,
			true
		);
		pendingValue.setHorizontalAlignment(SwingConstants.RIGHT);
		pendingRow.add(pendingValue, BorderLayout.EAST);
		statusCard.add(pendingRow);

		content.add(card(statusCard));
		addVerticalGap(10);

		// --- Items section ---
		content.add(sectionLabel("Items on loan"));
		addVerticalGap(6);

		if (status.loans == null || status.loans.isEmpty())
		{
			JPanel msg = new JPanel();
			msg.setLayout(new BoxLayout(msg, BoxLayout.Y_AXIS));
			fillWidth(msg, CARD_INNER_WIDTH);
			msg.add(label("Nothing on loan", OK_GREEN, 12f, false));
			content.add(card(msg));
		}
		else
		{
			for (ClanBankStatus.LoanEntry loan : status.loans)
			{
				content.add(itemRow(loan));
				addVerticalGap(6);
			}
		}

		refreshReturnOptions(status);
		finishRender();
	}

	// Small rounded-square background behind an item icon — the flat icon
	// floating on the row background read as an afterthought, this gives it
	// a visual anchor consistent with the rest of the redesign.
	private JPanel iconTile(String itemName, int size)
	{
		JPanel tile = new RoundedPanel(new BorderLayout(), ICON_TILE_RADIUS);
		tile.setBackground(ICON_TILE_BACKGROUND);
		tile.setPreferredSize(new Dimension(size, size));

		JLabel icon = new JLabel();
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		tile.add(icon, BorderLayout.CENTER);
		loadIconInto(itemName, icon);
		return tile;
	}

	private JPanel itemRow(ClanBankStatus.LoanEntry loan)
	{
		JPanel row = new RoundedPanel(new BorderLayout(8, 0), CARD_RADIUS);
		row.setBackground(CARD_BACKGROUND);
		row.setBorder(new EmptyBorder(6, 8, 6, 8));
		fillWidth(row, CARD_TARGET_WIDTH);
		row.add(iconTile(loan.itemName, ICON_SIZE), BorderLayout.WEST);

		// row's EmptyBorder (16px h) + icon tile + BorderLayout(8,0) gap
		int textWidth = CARD_TARGET_WIDTH - 16 - ICON_SIZE - 8;

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(CARD_BACKGROUND);
		fillWidth(text, textWidth);

		JPanel nameRow = new JPanel(new BorderLayout());
		nameRow.setBackground(CARD_BACKGROUND);
		fillWidth(nameRow, textWidth);
		nameRow.add(label(loan.itemName, Color.WHITE, 12f, true), BorderLayout.WEST);

		boolean gpRepayment = "gp".equals(loan.repaymentType);
		String owed = gpRepayment
			? ClanBankFormat.compactGp(loan.gpOwed) + " gp"
			: String.format("%,dx", loan.quantityOwed);
		JLabel owedLabel = label(owed, ColorScheme.LIGHT_GRAY_COLOR, 11f, false);
		if (gpRepayment)
		{
			owedLabel.setToolTipText(ClanBankFormat.exactGp(loan.gpOwed) + " owed");
		}
		owedLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		nameRow.add(owedLabel, BorderLayout.EAST);
		text.add(nameRow);

		if (loan.finalProduct != null && !loan.finalProduct.isEmpty()
			&& !loan.finalProduct.equalsIgnoreCase(loan.itemName))
		{
			text.add(label("for: " + loan.finalProduct, ColorScheme.LIGHT_GRAY_COLOR, 10f, false));
		}

		row.add(text, BorderLayout.CENTER);
		return row;
	}

	private void loadIconInto(String itemName, JLabel target)
	{
		AsyncBufferedImage cached = iconCache.get(itemName);
		if (cached != null)
		{
			cached.addTo(target);
			return;
		}

		executor.execute(() ->
		{
			try
			{
				List<ItemPrice> results = itemManager.search(itemName);
				if (results.isEmpty())
				{
					return;
				}
				ItemPrice best = results.stream()
					.filter(r -> r.getName().equalsIgnoreCase(itemName))
					.findFirst()
					.orElse(results.get(0));

				AsyncBufferedImage image = itemManager.getImage(best.getId());
				iconCache.put(itemName, image);
				SwingUtilities.invokeLater(() -> image.addTo(target));
			}
			catch (Exception e)
			{
				// Icon is cosmetic — a failed lookup just leaves the row without one.
			}
		});
	}

	private void finishRender()
	{
		// content is rebuilt from empty on every poll, so revalidate from the
		// panel root rather than from `content` — that way the ancestors
		// re-measure too once real children replace nothing.
		revalidate();
		repaint();
	}

