package com.creepsinc.clanbank;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Compact in-game summary of what you owe the clan bank.
 *
 * Painted by hand rather than assembled from RuneLite's stock
 * Title/Line/ProgressBar components — those stack as plain full-width text
 * rows, which is what made this look like a debug readout. Drawing directly
 * buys a rounded translucent card, a left accent stripe, right-aligned
 * values that can't wrap mid-number, a slim rounded cap bar, and a pill
 * badge for the pending count.
 */
class ClanBankOverlay extends Overlay
{
	private static final int WIDTH = 186;
	private static final int PAD = 10;
	private static final int TITLE_H = 14;
	private static final int DIVIDER_GAP = 9;
	private static final int ROW_H = 15;
	private static final int BAR_H = 5;
	private static final int BAR_GAP = 6;
	private static final int CORNER = 10;

	private static final Color BACKGROUND = new Color(24, 24, 24, 225);
	private static final Color BORDER = new Color(255, 152, 31, 70);
	private static final Color ACCENT = new Color(255, 152, 31);
	private static final Color LABEL = new Color(176, 174, 163);
	private static final Color TRACK = new Color(58, 58, 58);
	private static final Color OK_GREEN = new Color(0x8B, 0xC3, 0x4A);
	private static final Color DANGER = new Color(0xE2, 0x4B, 0x4A);

	private static final Font TITLE_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 12);
	private static final Font LABEL_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 11);
	private static final Font VALUE_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 11);
	private static final Font BADGE_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 10);

	private final ClanBankPlugin plugin;

	@Inject
	private ClanBankOverlay(ClanBankPlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final ClanBankStatus status = plugin.getStatus();
		final String error = plugin.getLastError();

		final String title = status != null && status.clanName != null ? status.clanName : "Clan bank";
		final String message = error != null && status == null ? error
			: status == null ? "Loading…"
			: !status.linked ? "No bank activity yet"
			: null;

		final boolean showBar = message == null && !status.noLimit;
		int height = PAD + TITLE_H + DIVIDER_GAP + ROW_H + PAD;
		if (message == null)
		{
			height += (showBar ? BAR_GAP + BAR_H : 0) + BAR_GAP + ROW_H;
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		g.setColor(BACKGROUND);
		g.fill(new RoundRectangle2D.Float(0, 0, WIDTH, height, CORNER, CORNER));
		g.setColor(BORDER);
		g.draw(new RoundRectangle2D.Float(0, 0, WIDTH - 1, height - 1, CORNER, CORNER));
		// Left accent stripe, clipped to the card's rounded corners.
		g.setClip(new RoundRectangle2D.Float(0, 0, WIDTH, height, CORNER, CORNER));
		g.setColor(ACCENT);
		g.fillRect(0, 0, 3, height);
		g.setClip(null);

		int y = PAD;

		g.setFont(TITLE_FONT);
		g.setColor(ACCENT);
		g.drawString(title, PAD, y + TITLE_H - 3);
		y += TITLE_H;

		g.setColor(new Color(255, 152, 31, 55));
		g.drawLine(PAD, y, WIDTH - PAD, y);
		y += DIVIDER_GAP;

		if (message != null)
		{
			g.setFont(LABEL_FONT);
			g.setColor(error != null && status == null ? DANGER : LABEL);
			g.drawString(message, PAD, y + ROW_H - 4);
			return new Dimension(WIDTH, height);
		}

		final boolean overCap = !status.noLimit && status.totalOutstandingGp >= status.loanCapGp;

		// --- Owed row ---
		g.setFont(LABEL_FONT);
		g.setColor(LABEL);
		g.drawString("Owed", PAD, y + ROW_H - 4);

		final String owed = status.noLimit
			? ClanBankFormat.compactGp(status.totalOutstandingGp) + " gp"
			: ClanBankFormat.compactGp(status.totalOutstandingGp) + " / " + ClanBankFormat.compactGp(status.loanCapGp);
		g.setFont(VALUE_FONT);
		g.setColor(overCap ? DANGER : Color.WHITE);
		drawRightAligned(g, owed, WIDTH - PAD, y + ROW_H - 4);
		y += ROW_H;

		// --- Cap bar ---
		if (showBar)
		{
			y += BAR_GAP;
			int barWidth = WIDTH - PAD * 2;
			g.setColor(TRACK);
			g.fill(new RoundRectangle2D.Float(PAD, y, barWidth, BAR_H, BAR_H, BAR_H));
			double ratio = Math.min(1.0, Math.max(0.0, (double) status.totalOutstandingGp / Math.max(1, status.loanCapGp)));
			int fill = (int) Math.round(barWidth * ratio);
			if (fill > 0)
			{
				g.setColor(overCap ? DANGER : OK_GREEN);
				g.fill(new RoundRectangle2D.Float(PAD, y, fill, BAR_H, BAR_H, BAR_H));
			}
			y += BAR_H;
		}

		// --- Pending row ---
		y += BAR_GAP;
		g.setFont(LABEL_FONT);
		g.setColor(LABEL);
		g.drawString("Pending approval", PAD, y + ROW_H - 4);

		final String pending = String.valueOf(status.pendingCount);
		if (status.pendingCount > 0)
		{
			g.setFont(BADGE_FONT);
			FontMetrics fm = g.getFontMetrics();
			int textWidth = fm.stringWidth(pending);
			int badgeWidth = Math.max(textWidth + 10, 16);
			int badgeHeight = 13;
			int badgeX = WIDTH - PAD - badgeWidth;
			int badgeY = y + (ROW_H - badgeHeight) / 2 - 1;
			g.setColor(ACCENT);
			g.fill(new RoundRectangle2D.Float(badgeX, badgeY, badgeWidth, badgeHeight, badgeHeight, badgeHeight));
			g.setColor(new Color(61, 34, 0));
			g.drawString(pending, badgeX + (badgeWidth - textWidth) / 2, badgeY + badgeHeight - 3);
		}
		else
		{
			g.setFont(VALUE_FONT);
			g.setColor(Color.WHITE);
			drawRightAligned(g, pending, WIDTH - PAD, y + ROW_H - 4);
		}

		return new Dimension(WIDTH, height);
	}

	private void drawRightAligned(Graphics2D g, String text, int rightEdge, int baseline)
	{
		g.drawString(text, rightEdge - g.getFontMetrics().stringWidth(text), baseline);
	}
}

